// pwp003-parse-json
// Parse parent_watcher.py JSON stdout and expose action_count for branching.
const data = $input.item.json;
const exitCode = data.exitCode != null ? Number(data.exitCode) : -1;
const stdout = String(data.stdout || '').trim();
const stderr = String(data.stderr || '').trim();

if (exitCode !== 0) {
  throw new Error('parent_watcher.py failed: ' + (stderr || ('exitCode=' + exitCode)));
}

if (!stdout) {
  throw new Error('parent_watcher.py returned empty stdout');
}

let parsed;
try {
  parsed = JSON.parse(stdout);
} catch (error) {
  throw new Error('Could not parse parent_watcher.py stdout as JSON: ' + error.message);
}

const actions = Array.isArray(parsed.actions) ? parsed.actions : [];
return {
  json: {
    ...parsed,
    action_count: actions.length,
    _exec: {
      exitCode,
      stderr
    }
  }
};

// pwp005-append-log
// Append one heartbeat row only when the watcher actually applied or proposed actions.
const fs = require('fs');
const LOG_PATH = '/miru-data/parent_watcher_runs.jsonl';
const data = $input.item.json;
const row = {
  ts: new Date().toISOString(),
  action_count: Number(data.action_count || 0),
  dry_run: !!data.dry_run,
  parents: Array.isArray(data.actions)
    ? data.actions.map((item) => item.parent || item.parent_identifier).filter(Boolean)
    : []
};
fs.appendFileSync(LOG_PATH, JSON.stringify(row) + '\n');
return { json: data };
